import React, { useState, useEffect } from 'react'
import { Loader2, FileText } from 'lucide-react'
import { CabinetHome } from './pages/CabinetHome'
import { CabinetSchedule } from './pages/CabinetSchedule'
import { CabinetRooms } from './pages/CabinetRooms'
import { CabinetQuestionnaire } from './pages/CabinetQuestionnaire'
import { CabinetMeetings } from './pages/CabinetMeetings'
import { CabinetLibrary } from './pages/CabinetLibrary'
import { NAV_ITEMS, SCHEDULE_SIDEBAR } from '../features/appshell/constants/navigation'
import { TopNavigation } from '../features/appshell/components/AppShell/TopNavigation'
import { AppSidebar } from '../features/appshell/components/AppShell/AppSidebar'
import { ProfileModal } from '../features/appshell/components/AppShell/ProfileModal'
import { ThemeModal } from '../features/appshell/components/AppShell/ThemeModal'
import { VersionModal } from '../features/appshell/components/AppShell/VersionModal'
import { CabinetAdmin } from './pages/CabinetAdmin'
import { CabinetReports } from './pages/CabinetReports'

export function CabinetAppShell({ children }) {
  const [activeNav, setActiveNav] = useState('home')
  const [activeSidebar, setActiveSidebar] = useState(0)

  const [isSidebarCollapsed, setIsSidebarCollapsed] = useState(false)
  const [userName, setUserName] = useState('Người dùng')
  const [userLoginName, setUserLoginName] = useState('022182002686')
  const [userLastLogin, setUserLastLogin] = useState('Lần đầu đăng nhập')

  const [isThemeModalOpen, setIsThemeModalOpen] = useState(false)
  const [isVersionModalOpen, setIsVersionModalOpen] = useState(false)
  const [isProfileModalOpen, setIsProfileModalOpen] = useState(false)
  const [isLoggingOut, setIsLoggingOut] = useState(false)

  const [notifications, setNotifications] = useState([])
  const [notifCount, setNotifCount] = useState(0)

  useEffect(() => {
    try {
      const token = localStorage.getItem('auth_token')
      if (token) {
        const payload = JSON.parse(window.atob(token.split('.')[1]))
        setUserName(
          payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name'] ||
            payload.unique_name ||
            payload.sub ||
            'Người dùng'
        )
        setUserLoginName(
          payload['http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier'] ||
            payload.unique_name ||
            '022182002686'
        )
        setUserLastLogin(payload.LastLogin || 'Lần đầu đăng nhập')
      }
    } catch {
      /* silent */
    }
  }, [])

  const fetchNotifications = async () => {
    try {
      const response = await fetch('/api/notification')
      if (response.ok) {
        const data = await response.json()
        setNotifications(data)
        setNotifCount(data.filter((n) => !n.isRead).length)
      }
    } catch (e) {
      console.error(e)
    }
  }

  const markAllRead = async () => {
    try {
      await fetch('/api/notification/mark-all-read', { method: 'POST' })
      fetchNotifications()
    } catch (e) {
      console.error(e)
    }
  }

  const markRead = async (id) => {
    try {
      await fetch(`/api/notification/mark-read/${id}`, { method: 'POST' })
      fetchNotifications()
    } catch (e) {
      console.error(e)
    }
  }

  useEffect(() => {
    fetchNotifications()
    const handleNotifUpdate = () => fetchNotifications()
    document.addEventListener('realtime:notifications_updated', handleNotifUpdate)
    return () => {
      document.removeEventListener('realtime:notifications_updated', handleNotifUpdate)
    }
  }, [])

  const handleLogout = () => {
    setIsProfileModalOpen(false)
    setIsLoggingOut(true)
    setTimeout(() => {
      localStorage.removeItem('auth_token')
      window.location.href = '/login'
    }, 1500)
  }

  const currentScheduleType = SCHEDULE_SIDEBAR[activeSidebar]?.type || 'personal'

  const renderPage = () => {
    switch (activeNav) {
      case 'home':
        return <CabinetHome />
      case 'schedule':
        return <CabinetSchedule scheduleType={currentScheduleType} />
      case 'manage_meetings':
        return <CabinetMeetings activeTab={activeSidebar} />
      case 'rooms':
        return <CabinetRooms activeTab={activeSidebar} />
      case 'questionnaire':
        return <CabinetQuestionnaire />
      case 'library':
        return <CabinetLibrary activeTab={activeSidebar} />
      case 'admin':
        return <CabinetAdmin activeTab={activeSidebar} />
      case 'reports':
        return <CabinetReports />
      default:
        return (
          <div className="flex-1 flex flex-col items-center justify-center text-gray-400">
            <div className="w-16 h-16 rounded-2xl bg-gray-50 flex items-center justify-center mb-4">
              <FileText size={28} className="opacity-25" />
            </div>
            <h3 className="text-base font-bold text-gray-600 mb-1">Đang phát triển</h3>
            <p className="text-sm">
              Tính năng &quot;{NAV_ITEMS.find((x) => x.id === activeNav)?.label}&quot; sẽ sớm được
              cập nhật.
            </p>
          </div>
        )
    }
  }

  return (
    <div className="flex flex-col h-screen w-screen overflow-hidden bg-gray-100 font-sans">
      <TopNavigation
        activeNav={activeNav}
        setActiveNav={setActiveNav}
        setActiveSidebar={setActiveSidebar}
        notifCount={notifCount}
        notifications={notifications}
        markAllRead={markAllRead}
        markRead={markRead}
        userName={userName}
        setIsProfileModalOpen={setIsProfileModalOpen}
        setIsThemeModalOpen={setIsThemeModalOpen}
        setIsVersionModalOpen={setIsVersionModalOpen}
        onLogout={handleLogout}
        isSidebarCollapsed={isSidebarCollapsed}
        setIsSidebarCollapsed={setIsSidebarCollapsed}
      />

      <div className="flex flex-1 overflow-hidden">
        <AppSidebar
          activeNav={activeNav}
          activeSidebar={activeSidebar}
          setActiveSidebar={setActiveSidebar}
          isSidebarCollapsed={isSidebarCollapsed}
        />

        <main className="flex-1 bg-gray-50 overflow-hidden relative flex flex-col">
          {children || renderPage()}
        </main>
      </div>

      <ProfileModal
        isOpen={isProfileModalOpen}
        onClose={setIsProfileModalOpen}
        userName={userName}
        userLoginName={userLoginName}
        userLastLogin={userLastLogin}
        onLogout={handleLogout}
      />

      <ThemeModal isOpen={isThemeModalOpen} onClose={setIsThemeModalOpen} />

      <VersionModal isOpen={isVersionModalOpen} onClose={setIsVersionModalOpen} />

      {isLoggingOut && (
        <div className="fixed inset-0 bg-black/60 z-50 flex flex-col items-center justify-center backdrop-blur-sm animate-in fade-in duration-300">
          <Loader2 className="w-12 h-12 text-white animate-spin mb-4" />
          <h2 className="text-white text-xl font-bold">Đang đăng xuất...</h2>
          <p className="text-gray-200 mt-2">Vui lòng chờ trong giây lát</p>
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
import { Search, Plus, RefreshCw, Download } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { useConclusions } from '../../features/conclusions/hooks/useConclusions'
import { ConclusionTable } from '../../features/conclusions/components/ConclusionTable'
import { ConclusionFormModal } from '../../features/conclusions/components/ConclusionFormModal'
import { conclusionApi } from '../../features/conclusions/api/conclusionApi'

export function CabinetConclusions() {
  const {
    data,
    total,
    meetings,
    loading,
    page,
    search,
    pageSize,
    setPage,
    setSearch,
    fetchData,
    createConclusion,
  } = useConclusions()

  const [isAddOpen, setIsAddOpen] = useState(false)
  const [saving, setSaving] = useState(false)
  const [formMeetingId, setFormMeetingId] = useState('')
  const [formFileName, setFormFileName] = useState('')
  const [formDocumentNumber, setFormDocumentNumber] = useState('')
  const [formDocumentDate, setFormDocumentDate] = useState('')
  const [formStatus, setFormStatus] = useState('Chưa xử lý')

  const totalPages = Math.ceil(total / pageSize)

  const handleSearch = (e) => {
    const q = e.target.value
    setSearch(q)
    setPage(1)
    fetchData(1, q)
  }

  const handleCreate = async () => {
    if (!formMeetingId) return
    setSaving(true)
    try {
      await createConclusion({
        meetingId: Number(formMeetingId),
        fileName: formFileName || null,
        documentNumber: formDocumentNumber || null,
        documentDate: formDocumentDate ? new Date(formDocumentDate).toISOString() : null,
        status: formStatus,
        progress: 0,
      })
      setIsAddOpen(false)
      setFormMeetingId('')
      setFormFileName('')
      setFormDocumentNumber('')
      setFormDocumentDate('')
      setFormStatus('Chưa xử lý')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="flex flex-col h-full bg-white rounded-lg p-6 shadow-sm">
      <div className="flex items-center justify-between mb-6">
        <h3 className="font-semibold text-xl text-slate-800">Tra cứu kết luận sau phiên họp</h3>
        <div className="flex gap-2">
          <Button
            variant="outline"
            className="border-green-600 text-green-700 hover:bg-green-50"
            onClick={async () => {
              try {
                const blob = await conclusionApi.export(search)
                const url = window.URL.createObjectURL(blob)
                const a = document.createElement('a')
                a.href = url
                a.download = `DanhSachKetLuan_${new Date().getTime()}.xls`
                document.body.appendChild(a)
                a.click()
                document.body.removeChild(a)
                window.URL.revokeObjectURL(url)
              } catch (e) {
                alert(e.message || 'Có lỗi khi xuất Excel')
              }
            }}
          >
            <Download className="h-4 w-4 mr-2" />
            Xuất Excel
          </Button>
          <Button
            onClick={() => setIsAddOpen(true)}
            className="bg-[var(--color-primary)] hover:bg-[#a50e27] text-white"
          >
            <Plus className="h-4 w-4 mr-2" />
            Thêm mới
          </Button>
        </div>
      </div>

      <div className="flex items-center justify-between mb-4">
        <div className="font-medium text-slate-800">Danh sách kết luận ({total})</div>
        <div className="flex items-center gap-2">
          <div className="relative w-[300px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Tìm kiếm theo tên phiên họp, file..."
              className="pl-9 bg-white"
              value={search}
              onChange={handleSearch}
            />
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="text-gray-500"
            onClick={() => fetchData(page, search)}
          >
            <RefreshCw className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <ConclusionTable data={data} loading={loading} page={page} pageSize={pageSize} />

      {totalPages > 1 && (
        <div className="flex items-center justify-end gap-2 mt-4">
          {Array.from({ length: totalPages }, (_, i) => (
            <button
              key={i + 1}
              onClick={() => {
                setPage(i + 1)
                fetchData(i + 1, search)
              }}
              className={`w-8 h-8 rounded text-sm font-medium transition ${page === i + 1 ? 'bg-[var(--color-primary)] text-white' : 'text-gray-700 hover:bg-gray-100 border border-gray-200'}`}
            >
              {i + 1}
            </button>
          ))}
        </div>
      )}

      <ConclusionFormModal
        open={isAddOpen}
        onOpenChange={setIsAddOpen}
        meetings={meetings}
        formMeetingId={formMeetingId}
        setFormMeetingId={setFormMeetingId}
        formFileName={formFileName}
        setFormFileName={setFormFileName}
        formDocumentNumber={formDocumentNumber}
        setFormDocumentNumber={setFormDocumentNumber}
        formDocumentDate={formDocumentDate}
        setFormDocumentDate={setFormDocumentDate}
        formStatus={formStatus}
        setFormStatus={setFormStatus}
        onSubmit={handleCreate}
        saving={saving}
      />
    </div>
  )
}

import React, { useState } from 'react'
import { LibraryLayout } from '../../features/documents/components/LibraryLayout'
import { LIBRARY_SIDEBAR } from '../../features/appshell/constants/navigation'

export function CabinetLibrary({ activeTab }) {
  const currentTab = LIBRARY_SIDEBAR[activeTab] || LIBRARY_SIDEBAR[0]

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Top Header */}
      <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between bg-white shrink-0">
        <h1 className="text-xl font-bold text-gray-800">{currentTab.label}</h1>
      </div>

      {/* Content Area */}
      <div className="flex-1 overflow-hidden relative">
        <LibraryLayout type={currentTab.type} label={currentTab.label} />
      </div>
    </div>
  )
}

import React, { useState, useEffect, useRef } from 'react'
import { ArrowLeft, Check, Calendar, Info } from 'lucide-react'
import { Button } from '@/components/ui/button'

import { Step1Details } from '../../features/meetings/components/MeetingCreate/Step1Details'
import { Step2Participants } from '../../features/meetings/components/MeetingCreate/Step2Participants'
import { Step3Contents } from '../../features/meetings/components/MeetingCreate/Step3Contents'
import { ProceedingCreateModal } from '../../features/proceedings/components/ProceedingModals'
import { proceedingApi } from '../../features/proceedings/api/proceedingApi'

export function CabinetMeetingCreate({ onBack, onSaved }) {
  const [step, setStep] = useState(1)
  const [loading, setLoading] = useState(false)
  const [rooms, setRooms] = useState([])
  const [proceedings, setProceedings] = useState([])
  const [users, setUsers] = useState([])
  const [departments, setDepartments] = useState([])

  const [showProceedingModal, setShowProceedingModal] = useState(false)
  const [proceedingName, setProceedingName] = useState('')
  const [proceedingDesc, setProceedingDesc] = useState('')
  const [proceedingMeetingId, setProceedingMeetingId] = useState('')
  const [savingProceeding, setSavingProceeding] = useState(false)

  const [formData, setFormData] = useState({
    title: '',
    proceedingId: '',
    singleContent: false,
    startTime: '',
    endTime: '',
    roomId: '',
    meetingType: '',
    onlineMeetingUrl: '',
    location: '',
  })

  const [selectedUsers, setSelectedUsers] = useState([])
  const [programFiles, setProgramFiles] = useState([])
  const [invitationFiles, setInvitationFiles] = useState([])

  const [participantTab, setParticipantTab] = useState('NhomThanhVien')
  const [groupType, setGroupType] = useState('')
  const [participantSearch, setParticipantSearch] = useState('')
  const [presidingUsers, setPresidingUsers] = useState([])

  const [contentTabs, setContentTabs] = useState([{ id: 1, title: 'Nội dung 1' }])
  const [activeContentTab, setActiveContentTab] = useState(1)

  const programInputRef = useRef(null)
  const invitationInputRef = useRef(null)

  useEffect(() => {
    fetch('/api/phonghopkhonggiayto/rooms')
      .then((r) => r.json())
      .then((j) => setRooms(j.data || j || []))
    fetch('/api/phonghopkhonggiayto/proceedings')
      .then((r) => r.json())
      .then((j) => setProceedings(j.data || j || []))
    fetch('/api/users')
      .then((r) => r.json())
      .then((j) => setUsers(j.data || j || []))
    fetch('/api/users/departments')
      .then((r) => r.json())
      .then((j) => setDepartments(j.data || j || []))
  }, [])

  const usersInSelectedDept = groupType
    ? users.filter((u) => u.departmentId === Number(groupType))
    : users

  const handleCreateProceeding = async () => {
    if (!proceedingName.trim()) return
    setSavingProceeding(true)
    try {
      const res = await proceedingApi.create({
        name: proceedingName.trim(),
        description: proceedingDesc.trim(),
        meetingId: null,
      })
      if (res.success) {
        const newProc = res.data
        setProceedings((prev) => [newProc, ...prev])
        setFormData((prev) => ({ ...prev, proceedingId: String(newProc.id) }))
        setShowProceedingModal(false)
        setProceedingName('')
        setProceedingDesc('')
      } else {
        alert(res.message || 'Lỗi tạo kỷ yếu')
      }
    } catch (e) {
      alert('Không thể kết nối đến máy chủ')
    }
    setSavingProceeding(false)
  }

  const handleSubmit = async () => {
    if (!formData.title || !formData.startTime || !formData.endTime) {
      alert('Vui lòng nhập đầy đủ tên phiên họp và thời gian')
      return
    }
    setLoading(true)
    const requestJson = {
      title: formData.title,
      startTime: formData.startTime,
      endTime: formData.endTime,
      roomId: formData.roomId ? parseInt(formData.roomId) : null,
      location: formData.location,
      proceedingId: formData.proceedingId ? parseInt(formData.proceedingId) : null,
      meetingType: formData.meetingType,
      onlineMeetingUrl: formData.onlineMeetingUrl,
      participantUserIds: presidingUsers, // mock selected users
    }
    const fd = new FormData()
    fd.append('requestJson', JSON.stringify(requestJson))
    programFiles.forEach((f) => fd.append('programFiles', f))
    invitationFiles.forEach((f) => fd.append('invitationFiles', f))

    try {
      const res = await fetch('/api/phonghopkhonggiayto/meetings', { method: 'POST', body: fd })
      const json = await res.json()
      if (res.ok && !json.error) onSaved()
      else alert(json.message || json.error || 'Có lỗi xảy ra')
    } catch (err) {
      alert('Lỗi kết nối máy chủ')
    } finally {
      setLoading(false)
    }
  }

  const steps = [
    { id: 1, title: 'Chi tiết phiên họp' },
    { id: 2, title: 'Thành phần tham dự' },
    { id: 3, title: 'Nội dung họp' },
    { id: 4, title: 'Sơ đồ vị trí' },
  ]

  return (
    <div className="flex-1 flex flex-col bg-gray-50 overflow-hidden">
      <div className="bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-4">
          <button
            onClick={onBack}
            className="p-1 hover:bg-gray-100 rounded-full transition text-gray-500"
          >
            <ArrowLeft size={20} />
          </button>
          <h1 className="text-xl font-bold text-gray-800">Tạo phiên họp mới</h1>
        </div>
        <div className="flex items-center gap-3">
          <Button
            variant="outline"
            className="text-blue-600 border-blue-200 bg-blue-50 hover:bg-blue-100"
          >
            <Calendar size={16} className="mr-2" /> Nhắc lịch họp
          </Button>
          <Button
            variant="outline"
            className="text-blue-600 border-blue-200 bg-blue-50 hover:bg-blue-100"
          >
            <Info size={16} className="mr-2" /> Thêm thông báo mới họp
          </Button>
        </div>
      </div>
      <div className="flex-1 overflow-auto p-6">
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm max-w-4xl mx-auto overflow-hidden flex flex-col">
          <div className="px-8 py-6 border-b border-gray-100 shrink-0">
            <div className="flex items-center justify-between relative">
              <div className="absolute left-0 top-1/2 -translate-y-1/2 w-full h-[2px] bg-gray-100 -z-10" />
              {steps.map((s) => {
                const isActive = step === s.id
                const isPassed = step > s.id
                return (
                  <div key={s.id} className="flex flex-col items-center gap-2 bg-white px-2">
                    <div
                      className={`w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold transition-colors ${isActive ? 'bg-[var(--color-primary)] text-white border-2 border-[var(--color-primary)]' : isPassed ? 'bg-white text-[var(--color-primary)] border-2 border-[var(--color-primary)]' : 'bg-white text-gray-400 border-2 border-gray-200'}`}
                    >
                      {isPassed ? <Check size={16} /> : s.id}
                    </div>
                    <span
                      className={`text-xs font-medium ${isActive || isPassed ? 'text-gray-800' : 'text-gray-400'}`}
                    >
                      {s.title}
                    </span>
                  </div>
                )
              })}
            </div>
          </div>
          <div className="flex-1 p-8 overflow-y-auto">
            {step === 1 && (
              <Step1Details
                formData={formData}
                setFormData={setFormData}
                proceedings={proceedings}
                rooms={rooms}
                programFiles={programFiles}
                setProgramFiles={setProgramFiles}
                programInputRef={programInputRef}
                invitationFiles={invitationFiles}
                setInvitationFiles={setInvitationFiles}
                invitationInputRef={invitationInputRef}
                onAddProceeding={() => setShowProceedingModal(true)}
              />
            )}
            {step === 2 && (
              <Step2Participants
                users={users}
                usersInSelectedDept={usersInSelectedDept}
                departments={departments}
                participantTab={participantTab}
                setParticipantTab={setParticipantTab}
                groupType={groupType}
                setGroupType={setGroupType}
                participantSearch={participantSearch}
                setParticipantSearch={setParticipantSearch}
                presidingUsers={presidingUsers}
                setPresidingUsers={setPresidingUsers}
              />
            )}
            {step === 3 && (
              <Step3Contents
                users={users}
                contentTabs={contentTabs}
                setContentTabs={setContentTabs}
                activeContentTab={activeContentTab}
                setActiveContentTab={setActiveContentTab}
              />
            )}
            {step === 4 && (
              <div className="text-center text-gray-500 py-10">Chưa hỗ trợ (Sơ đồ vị trí)</div>
            )}
          </div>
          <div className="px-8 py-4 border-t border-gray-100 flex justify-between items-center bg-gray-50 shrink-0">
            <div>
              <Button variant="outline" onClick={onBack} className="text-gray-600">
                Quay lại
              </Button>
            </div>
            <div className="flex items-center gap-3">
              <Button
                variant="outline"
                className="text-[var(--color-primary)] border-[var(--color-primary)] hover:bg-red-50"
              >
                Lưu nháp
              </Button>
              {step < steps.length ? (
                <Button
                  onClick={() => setStep((s) => s + 1)}
                  className="bg-[var(--color-primary)] hover:bg-red-700 text-white min-w-[120px]"
                >
                  Tiếp tục
                </Button>
              ) : (
                <Button
                  onClick={handleSubmit}
                  disabled={loading}
                  className="bg-[var(--color-primary)] hover:bg-red-700 text-white min-w-[120px]"
                >
                  {loading ? 'Đang lưu...' : 'Lưu phiên họp'}
                </Button>
              )}
            </div>
          </div>
        </div>
      </div>
      <ProceedingCreateModal
        open={showProceedingModal}
        onOpenChange={setShowProceedingModal}
        allMeetings={[]}
        formName={proceedingName}
        setFormName={setProceedingName}
        formDesc={proceedingDesc}
        setFormDesc={setProceedingDesc}
        formMeetingId={proceedingMeetingId}
        setFormMeetingId={setProceedingMeetingId}
        onSubmit={handleCreateProceeding}
        saving={savingProceeding}
      />
    </div>
  )
}

import React from 'react'
import { PositionManager } from '../../features/admin/components/PositionManager'

export function CabinetPositions() {
  return <PositionManager />
}

import React, { useState, useEffect } from 'react'
import { CabinetQuestionnaireTemplates } from './CabinetQuestionnaireTemplates'
import { CabinetQuestionnaireCreate } from './CabinetQuestionnaireCreate'
import { QuestionnaireSidebar } from '../../features/questionnaires/components/QuestionnaireList/QuestionnaireSidebar'
import { QuestionnaireHeader } from '../../features/questionnaires/components/QuestionnaireList/QuestionnaireHeader'
import { QuestionnaireTabs } from '../../features/questionnaires/components/QuestionnaireList/QuestionnaireTabs'
import { QuestionnaireTable } from '../../features/questionnaires/components/QuestionnaireList/QuestionnaireTable'
import { QuestionnaireMyList } from '../../features/questionnaires/components/QuestionnaireList/QuestionnaireMyList'
import { questionnaireApi } from '../../features/questionnaires/api/questionnaireApi'

export function CabinetQuestionnaire() {
  const [activeTab, setActiveTab] = useState('pending')
  const [activeSidebar, setActiveSidebar] = useState('list')
  const [mode, setMode] = useState('list') // 'list' | 'create'
  const [questionnaires, setQuestionnaires] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const pageSize = 10

  const fetchQuestionnaires = () => {
    setLoading(true)
    setPage(1)
    questionnaireApi
      .getAll()
      .then((json) => {
        if (json.success) {
          const data = Array.isArray(json.data) ? json.data : []
          setQuestionnaires(data)
        } else if (Array.isArray(json)) {
          setQuestionnaires(json)
        }
      })
      .catch((err) => console.error(err))
      .finally(() => setLoading(false))
  }

  useEffect(() => {
    fetchQuestionnaires()
  }, [])

  const filtered = questionnaires.filter(
    (q) => !search || q.title?.toLowerCase().includes(search.toLowerCase())
  )
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)

  return (
    <div className="flex-1 flex overflow-hidden bg-gray-50">
      <QuestionnaireSidebar
        activeSidebar={activeSidebar}
        setActiveSidebar={(val) => {
          setActiveSidebar(val)
          setMode('list')
        }}
        setMode={setMode}
      />

      {mode === 'create' ? (
        <CabinetQuestionnaireCreate
          onBack={() => setMode('list')}
          onSaved={() => {
            setMode('list')
            fetchQuestionnaires()
          }}
        />
      ) : activeSidebar === 'template' ? (
        <CabinetQuestionnaireTemplates />
      ) : activeSidebar === 'my' ? (
        <QuestionnaireMyList />
      ) : (
        <div className="flex-1 flex flex-col overflow-hidden">
          <QuestionnaireHeader setMode={setMode} />

          <QuestionnaireTabs activeTab={activeTab} setActiveTab={setActiveTab} />

          <QuestionnaireTable
            loading={loading}
            paged={paged}
            search={search}
            setSearch={setSearch}
            page={page}
            setPage={setPage}
            pageSize={pageSize}
            filteredLength={filtered.length}
            totalPages={totalPages}
            activeTab={activeTab}
            onRefresh={fetchQuestionnaires}
          />
        </div>
      )}
    </div>
  )
}

import { useState } from 'react'
import { ArrowLeft } from 'lucide-react'
import { useQuestionnaireCreate } from '../../features/questionnaires/hooks/useQuestionnaireCreate'
import { questionnaireApi } from '../../features/questionnaires/api/questionnaireApi'
import {
  QuestionnaireStepper,
  QuestionnaireStep1,
  QuestionnaireStep2,
  QuestionnaireStep3,
} from '../../features/questionnaires/components/QuestionnaireSteps'

export function CabinetQuestionnaireCreate({ onBack, onSaved }) {
  const { templates, users } = useQuestionnaireCreate()

  const [step, setStep] = useState(1)
  const [loading, setLoading] = useState(false)
  const [formData, setFormData] = useState({
    title: '',
    templateId: '',
    deadline: '',
    type: '',
    content: '',
  })
  const [selectedUsers, setSelectedUsers] = useState([])
  const [files, setFiles] = useState([])

  const toggleUser = (userId) =>
    setSelectedUsers((prev) =>
      prev.includes(userId) ? prev.filter((id) => id !== userId) : [...prev, userId]
    )

  const handleSubmit = async () => {
    if (!formData.title || !formData.deadline) {
      window.alert('Vui lòng nhập tên phiếu và hạn trả lời')
      return
    }
    setLoading(true)
    const fd = new FormData()
    fd.append('title', formData.title)
    if (formData.templateId) fd.append('templateId', formData.templateId)
    if (formData.type) fd.append('type', formData.type)
    if (formData.content) fd.append('content', formData.content)
    if (formData.deadline) fd.append('deadline', formData.deadline)
    fd.append('assignedUserIdsStr', JSON.stringify(selectedUsers))
    files.forEach((file) => fd.append('files', file))

    try {
      const json = await questionnaireApi.create(fd)
      if (json.success) onSaved()
      else window.alert(json.message || 'Có lỗi xảy ra')
    } catch (_e) {
      window.alert('Có lỗi xảy ra khi lưu phiếu')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="flex-1 flex flex-col bg-gray-50 overflow-hidden">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 px-6 py-4 flex items-center shrink-0">
        <button
          onClick={onBack}
          className="mr-3 p-1 hover:bg-gray-100 rounded-full transition text-gray-500"
        >
          <ArrowLeft size={20} />
        </button>
        <h1 className="text-xl font-bold text-gray-800">Thêm mới phiếu lấy ý kiến</h1>
      </div>

      <div className="flex-1 overflow-auto p-6">
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm max-w-4xl mx-auto overflow-hidden flex flex-col">
          <QuestionnaireStepper step={step} />

          {/* Content */}
          <div className="flex-1 p-8 overflow-y-auto">
            {step === 1 && (
              <QuestionnaireStep1
                formData={formData}
                setFormData={setFormData}
                templates={templates}
                files={files}
                setFiles={setFiles}
              />
            )}
            {step === 2 && <QuestionnaireStep2 formData={formData} setFormData={setFormData} />}
            {step === 3 && (
              <QuestionnaireStep3
                users={users}
                selectedUsers={selectedUsers}
                toggleUser={toggleUser}
              />
            )}
          </div>

          {/* Footer */}
          <div className="px-8 py-4 border-t border-gray-100 bg-gray-50/50 flex justify-between shrink-0">
            <button
              onClick={onBack}
              className="px-6 py-2 text-sm font-medium text-gray-600 border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors"
            >
              Hủy bỏ
            </button>
            <div className="flex gap-3">
              {step > 1 && (
                <button
                  onClick={() => setStep((s) => s - 1)}
                  className="px-6 py-2 text-sm font-medium text-[var(--color-primary)] bg-red-50 rounded-lg hover:bg-red-100 transition-colors"
                >
                  Quay lại
                </button>
              )}
              {step < 3 ? (
                <button
                  onClick={() => setStep((s) => s + 1)}
                  className="px-6 py-2 text-sm font-medium text-[var(--color-primary)] bg-red-50 rounded-lg hover:bg-red-100 transition-colors border border-transparent"
                >
                  Tiếp tục
                </button>
              ) : (
                <button
                  onClick={handleSubmit}
                  disabled={loading}
                  className="px-6 py-2 text-sm font-medium text-white bg-[var(--color-primary)] rounded-lg hover:bg-[#a50e27] transition-colors disabled:opacity-50"
                >
                  {loading ? 'Đang lưu...' : 'Lưu nháp'}
                </button>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { FileText } from 'lucide-react'
import { RoomModal } from '../../features/rooms/components/RoomModal'
import { DeleteConfirm } from '../../features/rooms/components/DeleteConfirm'
import { Toast } from '../../features/rooms/components/CabinetRooms/Toast'
import { RoomHeader } from '../../features/rooms/components/CabinetRooms/RoomHeader'
import { RoomTable } from '../../features/rooms/components/CabinetRooms/RoomTable'
import { ROOMS_SIDEBAR } from '../../features/appshell/constants/navigation'

export function CabinetRooms({ activeTab = 0 }) {
  const [rooms, setRooms] = useState([])
  const [departments, setDepartments] = useState([])
  const [loading, setLoading] = useState(true)
  const [search, setSearch] = useState('')
  const [page, setPage] = useState(1)
  const [togglingId, setTogglingId] = useState(null)
  const [modal, setModal] = useState(null)
  const [deleteTarget, setDeleteTarget] = useState(null)
  const [toast, setToast] = useState(null)
  const pageSize = 10

  const showToast = (message, type = 'success') => setToast({ message, type })

  const fetchRooms = useCallback(() => {
    setLoading(true)
    fetch('/api/phonghopkhonggiayto/rooms')
      .then((r) => r.json())
      .then((json) => setRooms(Array.isArray(json) ? json : json.data || []))
      .catch(() => setRooms([]))
      .finally(() => setLoading(false))
  }, [])

  useEffect(() => {
    fetchRooms()
    fetch('/api/phonghopkhonggiayto/rooms/departments')
      .then((r) => r.json())
      .then((json) => setDepartments(Array.isArray(json) ? json : json.data || []))
      .catch(() => setDepartments([]))
  }, [fetchRooms])

  const handleToggle = async (room) => {
    setTogglingId(room.id)
    const newStatus = room.status === 1 ? 0 : 1
    try {
      const res = await fetch(`/api/phonghopkhonggiayto/rooms/${room.id}/status`, {
        method: 'PUT',
        body: JSON.stringify({ status: newStatus }),
      })
      const json = await res.json()
      if (res.ok && json.success !== false) {
        setRooms((prev) => prev.map((r) => (r.id === room.id ? { ...r, status: newStatus } : r)))
        showToast(newStatus === 1 ? 'Đã bật phòng họp.' : 'Đã tắt phòng họp.')
      } else {
        showToast(json.message || 'Không thể cập nhật trạng thái.', 'error')
      }
    } catch {
      showToast('Lỗi kết nối máy chủ.', 'error')
    } finally {
      setTogglingId(null)
    }
  }

  const handleSaved = (savedRoom, action) => {
    if (!savedRoom || typeof savedRoom !== 'object') {
      fetchRooms()
      showToast(
        action === 'created' ? 'Thêm phòng họp thành công!' : 'Cập nhật phòng họp thành công!'
      )
      setModal(null)
      return
    }
    if (action === 'created') setRooms((prev) => [savedRoom, ...prev])
    else setRooms((prev) => prev.map((r) => (r.id === savedRoom.id ? savedRoom : r)))

    showToast(
      action === 'created' ? 'Thêm phòng họp thành công!' : 'Cập nhật phòng họp thành công!'
    )
    setModal(null)
  }

  const handleDeleted = (id) => {
    setRooms((prev) => prev.filter((r) => r.id !== id))
    setDeleteTarget(null)
    showToast('Xóa phòng họp thành công.')
  }

  const filtered = rooms.filter(
    (r) =>
      !search ||
      (r.name || '').toLowerCase().includes(search.toLowerCase()) ||
      (r.departmentName || '').toLowerCase().includes(search.toLowerCase())
  )
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paged = filtered.slice((page - 1) * pageSize, page * pageSize)

  if (activeTab > 0) {
    const tabLabel = ROOMS_SIDEBAR[activeTab]?.label || 'Tính năng'
    return (
      <div className="flex-1 flex flex-col items-center justify-center text-gray-400 bg-white">
        <div className="w-16 h-16 rounded-2xl bg-gray-50 flex items-center justify-center mb-4">
          <FileText size={28} className="opacity-25" />
        </div>
        <h3 className="text-base font-bold text-gray-600 mb-1">Đang phát triển</h3>
        <p className="text-sm">{tabLabel} sẽ sớm được cập nhật.</p>
      </div>
    )
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden">
      {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

      {modal && (
        <RoomModal
          mode={modal.mode}
          room={modal.room}
          departments={departments}
          onClose={() => setModal(null)}
          onSaved={handleSaved}
        />
      )}

      {deleteTarget && (
        <DeleteConfirm
          room={deleteTarget}
          onClose={() => setDeleteTarget(null)}
          onDeleted={handleDeleted}
        />
      )}

      <RoomHeader setModal={setModal} />

      <RoomTable
        rooms={rooms}
        loading={loading}
        search={search}
        setSearch={setSearch}
        page={page}
        setPage={setPage}
        pageSize={pageSize}
        filtered={filtered}
        paged={paged}
        totalPages={totalPages}
        setModal={setModal}
        setDeleteTarget={setDeleteTarget}
        handleToggle={handleToggle}
        togglingId={togglingId}
      />
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import FullCalendar from '@fullcalendar/react'
import dayGridPlugin from '@fullcalendar/daygrid'
import timeGridPlugin from '@fullcalendar/timegrid'
import interactionPlugin from '@fullcalendar/interaction'
import { ChevronLeft, ChevronRight, Plus } from 'lucide-react'
import { MeetingModal } from '../components/MeetingModal'
import { CabinetLeaderSchedule } from './CabinetLeaderSchedule'
import { CabinetUnitSchedule } from './CabinetUnitSchedule'
import { useSchedule } from '../../features/schedule/hooks/useSchedule'

export function CabinetSchedule({ scheduleType = 'personal' }) {
  const { calendarEvents: meetings, loading, fetchMeetings } = useSchedule('leader')
  const [viewMode, setViewMode] = useState('timeGridWeek')
  const [calendarTitle, setCalendarTitle] = useState('')
  const [modal, setModal] = useState(null) // null | { mode: 'add' } | { mode: 'edit', meeting }
  const calendarRef = useRef(null)

  const calendarApi = () => calendarRef.current?.getApi()

  const handlePrev = () => {
    calendarApi()?.prev()
    setCalendarTitle(calendarApi()?.view.title || '')
  }
  const handleNext = () => {
    calendarApi()?.next()
    setCalendarTitle(calendarApi()?.view.title || '')
  }
  const handleToday = () => {
    calendarApi()?.today()
    setCalendarTitle(calendarApi()?.view.title || '')
  }
  const handleViewChange = (v) => {
    setViewMode(v)
    calendarApi()?.changeView(v)
    setCalendarTitle(calendarApi()?.view.title || '')
  }

  useEffect(() => {
    setTimeout(() => {
      setCalendarTitle(calendarApi()?.view.title || '')
    }, 120)
  }, [])

  const handleSaved = () => {
    setModal(null)
    fetchMeetings()
  }

  const VIEW_BUTTONS = [
    { key: 'timeGridDay', label: 'Ngày' },
    { key: 'timeGridWeek', label: 'Tuần' },
    { key: 'dayGridMonth', label: 'Tháng' },
  ]

  if (scheduleType === 'leader') {
    return <CabinetLeaderSchedule />
  }

  if (scheduleType === 'unit') {
    return <CabinetUnitSchedule />
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-white">
      {/* Meeting modal */}
      {modal && (
        <MeetingModal
          meeting={modal.mode === 'edit' ? modal.meeting : null}
          onClose={() => setModal(null)}
          onSaved={handleSaved}
        />
      )}

      {/* Sub-header */}
      <div className="bg-white border-b border-gray-200 px-6 py-3 flex items-center justify-between shrink-0">
        <h1 className="text-xl font-bold text-gray-800">Lịch họp</h1>
        <button
          onClick={() => setModal({ mode: 'add' })}
          className="flex items-center gap-2 bg-[var(--color-primary)] hover:bg-[#a50e27] text-white px-4 py-2 rounded-lg text-sm font-semibold transition-colors shadow-sm"
        >
          <Plus size={15} />
          Tạo phiên họp mới
        </button>
      </div>

      {/* Calendar toolbar */}
      <div className="bg-white border-b border-gray-200 px-6 py-2.5 flex items-center justify-between shrink-0">
        <div className="flex items-center gap-2">
          <button
            onClick={handlePrev}
            className="w-8 h-8 flex items-center justify-center hover:bg-gray-100 rounded-full text-gray-600 transition"
          >
            <ChevronLeft size={17} />
          </button>
          <button
            onClick={handleToday}
            className="px-3 py-1 text-sm bg-gray-100 hover:bg-gray-200 rounded-md text-gray-700 font-medium transition"
          >
            Hôm nay
          </button>
          <span className="text-sm font-semibold text-gray-700 min-w-[220px] text-center">
            {calendarTitle}
          </span>
          <button
            onClick={handleNext}
            className="w-8 h-8 flex items-center justify-center hover:bg-gray-100 rounded-full text-gray-600 transition"
          >
            <ChevronRight size={17} />
          </button>
        </div>

        <div className="flex rounded-lg border border-gray-300 overflow-hidden text-sm">
          {VIEW_BUTTONS.map((btn) => (
            <button
              key={btn.key}
              onClick={() => handleViewChange(btn.key)}
              className={`px-4 py-1.5 font-medium transition-colors ${
                viewMode === btn.key
                  ? 'bg-[var(--color-primary)] text-white'
                  : 'bg-white text-gray-600 hover:bg-gray-50'
              }`}
            >
              {btn.label}
            </button>
          ))}
        </div>
      </div>

      {/* Calendar body */}
      <div className="flex-1 overflow-auto bg-white">
        {loading ? (
          <div className="flex items-center justify-center h-full">
            <div className="flex flex-col items-center gap-3 text-gray-400">
              <div className="w-8 h-8 border-2 border-[var(--color-primary)] border-t-transparent rounded-full animate-spin" />
              <span className="text-sm">Đang tải lịch họp...</span>
            </div>
          </div>
        ) : (
          <div
            className="h-full w-full"
            style={{
              '--fc-border-color': '#e5e7eb',
              '--fc-today-bg-color': 'rgba(200,16,46,0.04)',
              '--fc-now-indicator-color': '#c8102e',
            }}
          >
            <style>{`
              .fc-theme-standard .fc-scrollgrid { border: none !important; }
            `}</style>
            <FullCalendar
              ref={calendarRef}
              plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]}
              initialView={viewMode}
              headerToolbar={false}
              events={meetings}
              locale="vi"
              height="100%"
              slotMinTime="07:00:00"
              slotMaxTime="20:00:00"
              allDaySlot={false}
              nowIndicator={true}
              eventDisplay="block"
              eventClick={(info) => {
                // Fetch full meeting details (including participants) before opening modal
                fetch(`/api/phonghopkhonggiayto/meetings/${info.event.id}`)
                  .then((r) => r.json())
                  .then((json) => {
                    const fullMeeting = json.data || json
                    setModal({ mode: 'edit', meeting: fullMeeting })
                  })
                  .catch((err) => console.error('Failed to fetch meeting details', err))
              }}
              eventContent={(arg) => (
                <div
                  className="px-1.5 py-1 text-[11px] text-white h-full w-full overflow-hidden rounded cursor-pointer hover:brightness-90 transition-all"
                  style={{ backgroundColor: arg.event.backgroundColor || '#c8102e' }}
                >
                  <div className="font-bold leading-tight truncate">{arg.event.title}</div>
                  <div className="opacity-90 mt-0.5">{arg.timeText}</div>
                  <div className="opacity-75 truncate">{arg.event.extendedProps.room}</div>
                </div>
              )}
            />
          </div>
        )}
      </div>
    </div>
  )
}

import React from 'react'
import { SystemConfigManager } from '../../features/admin/components/SystemConfigManager'

export function CabinetSystemConfig() {
  return <SystemConfigManager />
}

import { useState, useEffect, useRef, useCallback } from 'react'
import FullCalendar from '@fullcalendar/react'
import dayGridPlugin from '@fullcalendar/daygrid'
import interactionPlugin from '@fullcalendar/interaction'
import multiMonthPlugin from '@fullcalendar/multimonth'
import { ChevronLeft, ChevronRight, Plus } from 'lucide-react'
import { MeetingModal } from '../components/MeetingModal'
import { useSchedule } from '../../features/schedule/hooks/useSchedule'

const getVietnameseDay = (dayIndex) => {
  const days = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy']
  return days[dayIndex]
}

export function CabinetUnitSchedule() {
  const { calendarEvents: meetings, loading, fetchMeetings } = useSchedule('unit')
  const [viewMode, setViewMode] = useState('dayGridWeek')
  const [calendarTitle, setCalendarTitle] = useState('')
  const [modal, setModal] = useState(null)
  const calendarRef = useRef(null)

  useEffect(() => {
    fetchMeetings()
  }, [fetchMeetings])

  const calendarApi = () => calendarRef.current?.getApi()

  const updateTitle = useCallback(() => {
    const api = calendarApi()
    if (!api) return
    const title = api.view.title
    // Format title if needed, or just use FullCalendar's built in vi locale title
    // "Thg 7 6 – 12, 2026" -> we might want to tweak it, but let's stick to default for now
    setCalendarTitle(title)
  }, [])

  const handlePrev = () => {
    calendarApi()?.prev()
    updateTitle()
  }
  const handleNext = () => {
    calendarApi()?.next()
    updateTitle()
  }
  const handleViewChange = (v) => {
    setViewMode(v)
    calendarApi()?.changeView(v)
    updateTitle()
  }

  useEffect(() => {
    setTimeout(updateTitle, 120)
  }, [updateTitle])

  const handleSaved = () => {
    setModal(null)
    fetchMeetings()
  }

  const VIEW_BUTTONS = [
    { key: 'dayGridWeek', label: 'Tuần' },
    { key: 'dayGridMonth', label: 'Tháng' },
    { key: 'multiMonthYear', label: 'Năm' },
  ]

  // Custom Day Header rendering
  const renderDayHeader = (arg) => {
    const d = arg.date
    if (viewMode === 'dayGridWeek') {
      const dayStr = getVietnameseDay(d.getDay())
      const dateStr = `${d.getDate()}/${d.getMonth() + 1}`
      return (
        <div className="font-semibold text-gray-700 py-1">
          {dayStr}, {dateStr}
        </div>
      )
    }
    return <div className="font-semibold text-gray-700 py-1">{arg.text}</div>
  }

  return (
    <div className="flex-1 flex flex-col overflow-hidden bg-gray-50">
      {modal && (
        <MeetingModal
          meeting={modal.mode === 'edit' ? modal.meeting : null}
          onClose={() => setModal(null)}
          onSaved={handleSaved}
        />
      )}

      {/* Main Title Header */}
      <div className="bg-gray-50 border-b border-gray-200 px-6 py-4 flex items-center shrink-0">
        <h1 className="text-xl font-bold text-[#1a202c]">Lịch họp</h1>
      </div>

      {/* Toolbar */}
      <div className="bg-white px-6 py-4 flex items-center justify-between shrink-0 m-4 mb-0 rounded-t-lg border border-gray-200 border-b-0">
        <div className="flex items-center gap-4">
          <span className="text-lg font-bold text-gray-900 min-w-[200px]">{calendarTitle}</span>
          <div className="flex items-center gap-1">
            <button
              onClick={handlePrev}
              className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-600 transition"
            >
              <ChevronLeft size={20} />
            </button>
            <button
              onClick={handleNext}
              className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-gray-100 text-gray-600 transition"
            >
              <ChevronRight size={20} />
            </button>
          </div>
        </div>

        <div className="flex rounded-lg border border-gray-300 overflow-hidden text-sm bg-gray-50 p-1">
          {VIEW_BUTTONS.map((btn) => (
            <button
              key={btn.key}
              onClick={() => handleViewChange(btn.key)}
              className={`px-6 py-1.5 font-medium transition-colors rounded-md ${
                viewMode === btn.key
                  ? 'bg-white text-gray-900 shadow-sm'
                  : 'text-gray-600 hover:text-gray-900'
              }`}
            >
              {btn.label}
            </button>
          ))}
        </div>
      </div>

      {/* Calendar body */}
      <div className="flex-1 overflow-auto px-4 pb-4">
        {loading ? (
          <div className="flex items-center justify-center h-full bg-white rounded-b-lg border border-t-0 border-gray-200">
            <div className="flex flex-col items-center gap-3 text-gray-400">
              <div className="w-8 h-8 border-2 border-[var(--color-primary)] border-t-transparent rounded-full animate-spin" />
              <span className="text-sm">Đang tải lịch họp...</span>
            </div>
          </div>
        ) : (
          <div
            className="h-full w-full bg-white rounded-b-lg border border-t-0 border-gray-200"
            style={{
              '--fc-border-color': '#f3f4f6',
              '--fc-today-bg-color': '#fce8e8', // Light pink/red background for today
              '--fc-event-bg-color': '#c8102e',
              '--fc-event-border-color': 'transparent',
            }}
          >
            <style>{`
              /* Make FullCalendar edges flush with container */
              .fc-theme-standard .fc-scrollgrid { border: none !important; }
              /* Minimal styling overrides */
              .fc-col-header-cell { padding-top: 8px; padding-bottom: 8px; }
              .fc-daygrid-day-top { flex-direction: row; justify-content: center; padding-top: 4px; }
              .fc-daygrid-day-number { font-size: 0.875rem; color: #4b5563; font-weight: 500; }
              .fc-event { border-radius: 4px; padding: 2px 4px; margin-bottom: 2px; }
              .fc-multimonth-daygrid { background-color: white; }
            `}</style>
            <FullCalendar
              ref={calendarRef}
              plugins={[dayGridPlugin, interactionPlugin, multiMonthPlugin]}
              initialView={viewMode}
              headerToolbar={false}
              events={meetings}
              locale="vi"
              height="100%"
              dayHeaderContent={renderDayHeader}
              eventClick={(info) => {
                fetch(`/api/phonghopkhonggiayto/meetings/${info.event.id}`)
                  .then((r) => r.json())
                  .then((json) => {
                    const fullMeeting = json.data || json
                    setModal({ mode: 'edit', meeting: fullMeeting })
                  })
                  .catch((err) => console.error('Failed to fetch meeting details', err))
              }}
              eventContent={(arg) => (
                <div className="text-[11px] text-white w-full overflow-hidden cursor-pointer hover:brightness-90 transition-all px-1">
                  <div className="font-bold leading-tight truncate">{arg.event.title}</div>
                  <div className="opacity-90 truncate">{arg.event.extendedProps.room}</div>
                </div>
              )}
            />
          </div>
        )}
      </div>
    </div>
  )
}

import React, { useState, useRef, useEffect } from 'react'
