            className="bg-white border-y border-l border-[var(--color-primary)] rounded-l-full flex items-center shadow-md overflow-hidden h-12"
          >
            <div className="bg-[var(--color-primary)] text-white w-9 h-9 flex items-center justify-center rounded-md ml-1.5 shrink-0">
              <Book size={18} />
            </div>
            <span className="text-[var(--color-primary)] font-bold px-3 whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity">
              Sổ tay
            </span>
          </button>
        </div>

        <NotebookModal isOpen={isNoteModalOpen} setIsOpen={setIsNoteModalOpen} meeting={meeting} />

        {/* Modal Thêm góp ý */}
        {isGopYOpen && (
          <div className="fixed inset-0 z-50 flex items-center justify-center">
            <div
              className="absolute inset-0 bg-black/40 backdrop-blur-sm"
              onClick={() => setIsGopYOpen(false)}
            />
            <div className="relative bg-white rounded-2xl shadow-2xl w-full max-w-lg mx-4">
              {/* Header */}
              <div className="flex items-center justify-between px-6 py-4 border-b border-gray-100">
                <h2 className="text-base font-bold text-gray-900">Thêm mới góp ý</h2>
                <button
                  onClick={() => setIsGopYOpen(false)}
                  className="text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg p-1 transition"
                >
                  <X size={18} />
                </button>
              </div>

              {/* Body */}
              <div className="px-6 py-5 space-y-4">
                {/* Góp ý cho nội dung */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1.5">
                    Góp ý cho nội dung <span className="text-[var(--color-primary)]">*</span>
                  </label>
                  <select
                    value={gopYContent}
                    onChange={(e) => setGopYContent(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]/25 focus:border-[var(--color-primary)] transition bg-white"
                  >
                    <option value="">-- Chọn nội dung --</option>
                    <option value={meeting.content || meeting.title}>
                      {meeting.content || meeting.title || 'Nội dung họp'}
                    </option>
                  </select>
                </div>

                {/* Tài liệu cần góp ý */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1.5">
                    Tài liệu cần góp ý
                  </label>
                  <select
                    value={gopYDoc}
                    onChange={(e) => setGopYDoc(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]/25 focus:border-[var(--color-primary)] transition bg-white"
                  >
                    <option value="">Chọn tài liệu</option>
                    {(meeting.documents || []).map((doc, idx) => (
                      <option key={idx} value={doc.name || doc}>
                        {doc.name || doc}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Chi tiết góp ý */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1.5">
                    Chi tiết góp ý <span className="text-[var(--color-primary)]">*</span>
                  </label>
                  <textarea
                    rows={4}
                    placeholder="Nhập nội dung góp ý"
                    value={gopYDetail}
                    onChange={(e) => setGopYDetail(e.target.value)}
                    className="w-full border border-gray-300 rounded-lg px-3 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-[var(--color-primary)]/25 focus:border-[var(--color-primary)] transition resize-none"
                  />
                </div>

                {/* Tài liệu đính kèm */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-1.5">
                    Tài liệu đính kèm
                  </label>
                  <div
                    className="border-2 border-dashed border-gray-300 rounded-lg px-4 py-5 text-center cursor-pointer hover:border-[var(--color-primary)] hover:bg-red-50/30 transition"
                    onClick={() => gopYFileRef.current?.click()}
                    onDragOver={(e) => e.preventDefault()}
                    onDrop={(e) => {
                      e.preventDefault()
                      const files = Array.from(e.dataTransfer.files)
                      setGopYFiles((prev) => [...prev, ...files])
                    }}
                  >
                    <Upload size={20} className="mx-auto text-[var(--color-primary)] mb-1" />
                    <p className="text-sm">
                      <span className="text-[var(--color-primary)] font-semibold">Chọn file</span>
                      <span className="text-gray-500"> hoặc Kéo thả từ máy tính</span>
                    </p>
                    <p className="text-xs text-gray-400 mt-1">
                      Tối đa 50MB, định dạng .doc, .docx, .xls, .xlsx, .ppt, .pptx, .pdf
                    </p>
                  </div>
                  <input
                    ref={gopYFileRef}
                    type="file"
                    multiple
                    accept=".doc,.docx,.xls,.xlsx,.ppt,.pptx,.pdf"
                    className="hidden"
                    onChange={(e) => {
                      if (e.target.files)
                        setGopYFiles((prev) => [...prev, ...Array.from(e.target.files)])
                    }}
                  />
                  {gopYFiles.length > 0 && (
                    <ul className="mt-2 space-y-1">
                      {gopYFiles.map((f, i) => (
                        <li
                          key={i}
                          className="flex items-center justify-between text-xs text-gray-600 bg-gray-50 px-3 py-1.5 rounded"
                        >
                          <span className="truncate">{f.name}</span>
                          <button
                            onClick={() =>
                              setGopYFiles((prev) => prev.filter((_, idx) => idx !== i))
                            }
                            className="text-gray-400 hover:text-red-500 ml-2 shrink-0"
                          >
                            <X size={13} />
                          </button>
                        </li>
                      ))}
                    </ul>
                  )}
                </div>
              </div>

              {/* Footer */}
              <div className="flex justify-end gap-3 px-6 py-4 border-t border-gray-100">
                <button
                  onClick={() => setIsGopYOpen(false)}
                  className="px-5 py-2 text-sm border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 font-medium transition"
                >
                  Hủy bỏ
                </button>
                <button
                  onClick={handleGopYSubmit}
                  disabled={gopYSaving || !gopYDetail.trim()}
                  className="px-5 py-2 text-sm bg-[var(--color-primary)] hover:bg-[#a50e27] text-white rounded-lg font-semibold transition disabled:opacity-60"
                >
                  {gopYSaving ? 'Đang gửi...' : 'Góp ý'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
      {renderAbsenceModal()}
    </>
  )

  // Modal Báo vắng appended inline
  function renderAbsenceModal() {
    if (!isAbsenceModalOpen) return null
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
        <div className="bg-white rounded-2xl shadow-2xl w-full max-w-md mx-4 overflow-hidden">
          <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
            <h2 className="text-lg font-bold text-gray-900 flex items-center gap-2">
              <UserX size={20} className="text-amber-500" /> Báo vắng
            </h2>
            <button
              onClick={() => setIsAbsenceModalOpen(false)}
              className="text-gray-400 hover:text-gray-600"
            >
              <X size={20} />
            </button>
          </div>
          <div className="px-6 py-5 space-y-4">
            <p className="text-sm text-gray-600">
              Vui lòng nhập lý do vắng mặt cho phiên họp{' '}
              <span className="font-semibold text-gray-900">{meeting.title}</span>.
            </p>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Lý do vắng mặt <span className="text-red-500">*</span>
              </label>
              <textarea
                className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:ring-2 focus:ring-amber-400 focus:border-amber-400 outline-none resize-none"
                rows={3}
                placeholder="Nhập lý do vắng mặt..."
                value={absenceReason}
                onChange={(e) => setAbsenceReason(e.target.value)}
              />
            </div>
          </div>
          <div className="flex justify-end gap-3 px-6 py-4 border-t border-gray-100">
            <button
              onClick={() => setIsAbsenceModalOpen(false)}
              className="px-5 py-2 text-sm border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 font-medium transition"
            >
              Hủy bỏ
            </button>
            <button
              disabled={absenceSaving || !absenceReason.trim()}
              onClick={async () => {
                setAbsenceSaving(true)
                try {
                  const res = await meetingApi.reportAbsence(meeting.id, absenceReason, null)
                  if (res.success) {
                    setIsAbsenceModalOpen(false)
                    setAbsenceReason('')
                    alert(res.message || 'Đã gửi báo cáo vắng mặt.')
                  } else {
                    alert(res.message || 'Không thể gửi báo cáo.')
                  }
                } catch {
                  alert('Không thể kết nối máy chủ.')
                } finally {
                  setAbsenceSaving(false)
                }
              }}
              className="px-5 py-2 text-sm bg-amber-500 hover:bg-amber-600 text-white rounded-lg font-semibold transition disabled:opacity-60"
            >
              {absenceSaving ? 'Đang gửi...' : 'Gửi báo cáo vắng'}
            </button>
          </div>
        </div>
      </div>
    )
  }
}

import React, { useState } from 'react'
import { Plus, Download } from 'lucide-react'
import { Button } from '@/components/ui/button'

import { MeetingDetail } from './MeetingDetail'
import { MeetingProgress } from './MeetingProgress'
import { MeetingModal } from '../components/MeetingModal'
import { CabinetMeetingCreate } from './CabinetMeetingCreate'
import { useMeetingList } from '../../features/meetings/hooks/useMeetingList'

import { MeetingStats } from '../../features/meetings/components/MeetingList/MeetingStats'
import { MeetingFilters } from '../../features/meetings/components/MeetingList/MeetingFilters'
import { MeetingTable } from '../../features/meetings/components/MeetingList/MeetingTable'
import { MeetingPagination } from '../../features/meetings/components/MeetingList/MeetingPagination'
import { AttendanceConfirmModal } from '../../features/home/components/CabinetHome/AttendanceConfirmModal'
import { SaveToLibraryModal } from '../../features/meetings/components/MeetingList/SaveToLibraryModal'

export function MeetingList() {
  const {
    meetings,
    loading,
    activeTab,
    setActiveTab,
    isAdmin,
    fetchMeetings,
    deleteMeeting,
    confirmAttendance,
  } = useMeetingList()

  const [searchQuery, setSearchQuery] = useState('')
  const [selectedMeeting, setSelectedMeeting] = useState(null)
  const [showProgress, setShowProgress] = useState(false)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(10)
  const [isAddModalOpen, setIsAddModalOpen] = useState(false)
  const [isCreating, setIsCreating] = useState(false)
  const [confirmMeeting, setConfirmMeeting] = useState(null)
  const [saveLibraryMeeting, setSaveLibraryMeeting] = useState(null)

  const filteredMeetings = meetings.filter((m) => {
    const matchSearch = m.title?.toLowerCase().includes(searchQuery.toLowerCase())
    if (!matchSearch) return false

    if (activeTab === 'prepare') {
      const noDocs =
        !m.programFilePaths || m.programFilePaths === '[]' || m.programFilePaths === 'null'
      return m.status === 'Sắp diễn ra' && noDocs
    }

    // For 'invited' tab, filter out 'all' logic if admin wants only invited (handled by backend though)
    return true
  })
  const paginatedMeetings = filteredMeetings.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  )

  if (isCreating) {
    return (
      <CabinetMeetingCreate
        onBack={() => setIsCreating(false)}
        onSaved={() => {
          setIsCreating(false)
          fetchMeetings(activeTab)
        }}
      />
    )
  }

  if (selectedMeeting) {
    if (showProgress)
      return <MeetingProgress meeting={selectedMeeting} onBack={() => setShowProgress(false)} />
    return (
      <MeetingDetail
        meeting={selectedMeeting}
        onBack={() => setSelectedMeeting(null)}
        onViewProgress={() => setShowProgress(true)}
      />
    )
  }

  return (
    <div className="flex-1 flex flex-col bg-gray-50 h-full overflow-hidden">
      {/* Header */}
      <div className="bg-white px-6 py-4 flex items-center justify-between border-b border-gray-200 shrink-0">
        <h1 className="text-xl font-bold text-[#1a202c]">Quản lý phiên họp</h1>
        <div className="flex items-center gap-3">
          {isAdmin && (
            <Button
              onClick={() => setIsCreating(true)}
              className="bg-[var(--color-primary)] hover:bg-[#a50e27] text-white"
            >
              <Plus className="w-4 h-4 mr-2" />
              Tạo phiên họp
            </Button>
          )}
          <Button
            variant="outline"
            className="text-[var(--color-primary)] border-[var(--color-primary)] hover:bg-red-50"
          >
            <Download className="w-4 h-4 mr-2" />
            Xuất file
          </Button>
        </div>
      </div>

      <AttendanceConfirmModal
        confirmMeeting={confirmMeeting}
        setConfirmMeeting={setConfirmMeeting}
        handleConfirmAttendance={(status) => {
          confirmAttendance(confirmMeeting.id, status)
          setConfirmMeeting(null)
        }}
      />
      <SaveToLibraryModal
        open={!!saveLibraryMeeting}
        onOpenChange={(open) => !open && setSaveLibraryMeeting(null)}
        meeting={saveLibraryMeeting}
        onSaved={() => alert('Đã lưu tài liệu thành công')}
      />

      <div className="flex-1 overflow-auto p-6">
        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-6">
          {/* Sub Tabs */}
          <div className="flex border-b border-gray-200 mb-6">
            {[
              { key: 'invited', label: 'Phiên họp cá nhân được mời' },
              { key: 'prepare', label: 'Phiên họp cần chuẩn bị tài liệu' },
              ...(isAdmin ? [{ key: 'all', label: 'Tất cả phiên họp' }] : []),
            ].map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`flex-1 pb-3 text-center font-semibold text-sm transition-colors border-b-2 ${activeTab === tab.key ? 'border-[var(--color-primary)] text-[var(--color-primary)]' : 'border-transparent text-gray-500 hover:text-gray-700'}`}
              >
                {tab.label}
              </button>
            ))}
          </div>

          <MeetingStats activeTab={activeTab} meetings={meetings} />

          <MeetingFilters
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            fetchMeetings={fetchMeetings}
          />

          <MeetingTable
            loading={loading}
            paginatedMeetings={paginatedMeetings}
            currentPage={currentPage}
            pageSize={pageSize}
            activeTab={activeTab}
            isAdmin={isAdmin}
            setSelectedMeeting={setSelectedMeeting}
            deleteMeeting={deleteMeeting}
            setConfirmMeeting={setConfirmMeeting}
            setSaveLibraryMeeting={setSaveLibraryMeeting}
          />

          {!loading && filteredMeetings.length > 0 && (
            <MeetingPagination
              currentPage={currentPage}
              setCurrentPage={setCurrentPage}
              pageSize={pageSize}
              setPageSize={setPageSize}
              totalItems={filteredMeetings.length}
            />
          )}
        </div>
      </div>

      {isAddModalOpen && (
        <MeetingModal
          onClose={() => setIsAddModalOpen(false)}
          onSaved={() => {
            setIsAddModalOpen(false)
            fetchMeetings()
          }}
        />
      )}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Card, CardHeader, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from '@/components/ui/table'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Edit, Trash2, Plus, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { ConfirmationModal } from '@/components/ui/confirmation-modal'

export function PositionManager() {
  const [positions, setPositions] = useState([])
  const [loading, setLoading] = useState(true)
  const [isOpen, setIsOpen] = useState(false)
  const [editingId, setEditingId] = useState(null)
  const [form, setForm] = useState({ name: '', description: '' })

  const [deleteId, setDeleteId] = useState(null)
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false)

  useEffect(() => {
    fetchPositions()
  }, [])

  const fetchPositions = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/admin/positions')
      if (res.ok) {
        const json = await res.json()
        setPositions(json.data || [])
      }
    } catch (e) {
      toast.error('Lỗi khi tải danh sách chức vụ')
    } finally {
      setLoading(false)
    }
  }

  const handleOpen = (pos = null) => {
    if (pos) {
      setEditingId(pos.id)
      setForm({ name: pos.name, description: pos.description || '' })
    } else {
      setEditingId(null)
      setForm({ name: '', description: '' })
    }
    setIsOpen(true)
  }

  const handleSave = async () => {
    if (!form.name) return toast.error('Vui lòng nhập tên chức vụ')

    try {
      const isEdit = !!editingId
      const res = await fetch(
        isEdit ? `/api/admin/positions/${editingId}` : '/api/admin/positions',
        {
          method: isEdit ? 'PUT' : 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(isEdit ? { id: editingId, ...form } : form),
        }
      )
      const json = await res.json()
      if (res.ok) {
        toast.success(isEdit ? 'Cập nhật thành công' : 'Thêm mới thành công')
        setIsOpen(false)
        fetchPositions()
      } else {
        toast.error(json.message || 'Có lỗi xảy ra')
      }
    } catch (e) {
      toast.error('Lỗi kết nối')
    }
  }

  const confirmDelete = async () => {
    if (!deleteId) return
    try {
      const res = await fetch(`/api/admin/positions/${deleteId}`, { method: 'DELETE' })
      const json = await res.json()
      if (res.ok) {
        toast.success('Xóa thành công')
        setIsDeleteModalOpen(false)
        fetchPositions()
      } else {
        toast.error(json.message || 'Xóa thất bại')
      }
    } catch (e) {
      toast.error('Lỗi kết nối')
    }
  }

  return (
    <div className="p-6 h-full flex flex-col">
      <div className="flex justify-between items-center mb-6">
        <div>
          <h1 className="text-2xl font-bold text-[#1a202c]">Quản lý Chức vụ</h1>
          <p className="text-sm text-gray-500 mt-1">Quản lý danh mục các chức vụ trong hệ thống</p>
        </div>
        <Button
          onClick={() => handleOpen()}
          className="bg-[var(--color-primary)] hover:bg-[#a50e27] text-white gap-2"
        >
          <Plus size={16} /> Thêm chức vụ
        </Button>
      </div>

      <Card className="flex-1 overflow-hidden flex flex-col shadow-sm border-0 ring-1 ring-gray-200">
        <CardContent className="p-0 overflow-auto flex-1">
          {loading ? (
            <div className="flex justify-center items-center h-40">
              <Loader2 className="w-8 h-8 text-[var(--color-primary)] animate-spin" />
            </div>
          ) : (
            <Table>
              <TableHeader className="bg-gray-50/80 sticky top-0 z-10">
                <TableRow>
                  <TableHead className="w-16">STT</TableHead>
                  <TableHead>Tên chức vụ</TableHead>
                  <TableHead>Mô tả</TableHead>
                  <TableHead className="text-right w-24">Thao tác</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {positions.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center py-10 text-gray-500">
                      Chưa có dữ liệu chức vụ
                    </TableCell>
                  </TableRow>
                ) : (
                  positions.map((pos, i) => (
                    <TableRow key={pos.id} className="hover:bg-gray-50/50">
                      <TableCell className="font-medium text-gray-500">{i + 1}</TableCell>
                      <TableCell className="font-semibold text-gray-900">{pos.name}</TableCell>
                      <TableCell className="text-gray-600">{pos.description || '-'}</TableCell>
                      <TableCell className="text-right">
                        <div className="flex justify-end gap-2">
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                            onClick={() => handleOpen(pos)}
                          >
                            <Edit size={16} />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50"
                            onClick={() => {
                              setDeleteId(pos.id)
                              setIsDeleteModalOpen(true)
                            }}
                          >
                            <Trash2 size={16} />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingId ? 'Sửa chức vụ' : 'Thêm chức vụ mới'}</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 mt-4">
            <div>
              <Label>
                Tên chức vụ <span className="text-red-500">*</span>
              </Label>
              <Input
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                placeholder="VD: Giám đốc..."
              />
            </div>
            <div>
              <Label>Mô tả</Label>
              <Input
                value={form.description}
                onChange={(e) => setForm({ ...form, description: e.target.value })}
                placeholder="Mô tả ngắn gọn"
              />
            </div>
          </div>
          <DialogFooter className="mt-6">
            <Button variant="outline" onClick={() => setIsOpen(false)}>
              Hủy
            </Button>
            <Button
              onClick={handleSave}
              className="bg-[var(--color-primary)] hover:bg-[#a50e27] text-white"
            >
              {editingId ? 'Cập nhật' : 'Thêm mới'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <ConfirmationModal
        isOpen={isDeleteModalOpen}
        onClose={() => setIsDeleteModalOpen(false)}
        onConfirm={confirmDelete}
        title="Xóa chức vụ"
        description="Bạn có chắc chắn muốn xóa chức vụ này? Hành động này không thể hoàn tác."
        confirmText="Xóa chức vụ"
        cancelText="Hủy"
        variant="destructive"
      />
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Card, CardHeader, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { toast } from 'sonner'
import { Loader2, Save } from 'lucide-react'

export function SystemConfigManager() {
  const [configs, setConfigs] = useState({
    PrimaryColor: '#c8102e',
    AppLogo: '/assets/logo.png',
    AppName: 'Cabinet Phòng họp không giấy',
  })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    fetchConfigs()
  }, [])

  const fetchConfigs = async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/admin/configs')
      if (res.ok) {
        const json = await res.json()
        if (json.data) {
          setConfigs({ ...configs, ...json.data })
        }
      }
    } catch (e) {
      toast.error('Lỗi tải cấu hình')
    } finally {
      setLoading(false)
    }
  }

  const handleSave = async () => {
    setSaving(true)
    try {
      const res = await fetch('/api/admin/configs', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('auth_token')}`,
        },
        body: JSON.stringify(configs),
      })
      if (res.ok) {
        toast.success('Cập nhật cấu hình thành công. Vui lòng tải lại trang để áp dụng.')
        // Dispatch event if we want to apply color immediately without reload
        document.documentElement.style.setProperty('--primary-color', configs.PrimaryColor)
      } else {
        const json = await res.json()
        toast.error(json.message || 'Có lỗi xảy ra')
      }
    } catch (e) {
      toast.error('Lỗi kết nối')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="p-6 h-full flex flex-col max-w-4xl mx-auto w-full">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-[#1a202c]">Cấu hình hệ thống</h1>
        <p className="text-sm text-gray-500 mt-1">
          Thiết lập logo, tên hệ thống và màu sắc chủ đạo
        </p>
      </div>

      <Card className="flex-1 shadow-sm border-0 ring-1 ring-gray-200">
        <CardContent className="p-6">
          {loading ? (
            <div className="flex justify-center items-center h-40">
              <Loader2 className="w-8 h-8 text-[var(--color-primary)] animate-spin" />
            </div>
          ) : (
            <div className="space-y-6">
              <div>
                <Label className="text-gray-700 font-semibold mb-2 block">Tên hệ thống</Label>
                <Input
                  value={configs.AppName || ''}
                  onChange={(e) => setConfigs({ ...configs, AppName: e.target.value })}
                  placeholder="VD: Cabinet Phòng họp không giấy"
                  className="max-w-md"
                />
              </div>

              <div>
                <Label className="text-gray-700 font-semibold mb-2 block">Logo URL</Label>
                <div className="flex gap-4 items-center">
                  <Input
                    value={configs.AppLogo || ''}
                    onChange={(e) => setConfigs({ ...configs, AppLogo: e.target.value })}
                    placeholder="/assets/logo.png hoặc https://..."
                    className="max-w-md"
                  />
                  {configs.AppLogo && (
                    <div className="h-10 px-4 bg-gray-100 rounded-lg flex items-center justify-center border">
                      <img
                        src={configs.AppLogo}
                        alt="Logo Preview"
                        className="max-h-8 object-contain"
                        onError={(e) => (e.target.style.display = 'none')}
                      />
                    </div>
                  )}
                </div>
              </div>

              <div>
                <Label className="text-gray-700 font-semibold mb-2 block">
                  Màu sắc chủ đạo (Primary Color)
                </Label>
                <div className="flex gap-4 items-center">
                  <Input
                    type="color"
                    value={configs.PrimaryColor || '#c8102e'}
                    onChange={(e) => setConfigs({ ...configs, PrimaryColor: e.target.value })}
                    className="w-16 h-10 p-1 cursor-pointer"
                  />
                  <Input
                    type="text"
                    value={configs.PrimaryColor || '#c8102e'}
                    onChange={(e) => setConfigs({ ...configs, PrimaryColor: e.target.value })}
                    className="w-32 uppercase"
                  />
                  <div className="text-sm text-gray-500">
                    Màu mặc định:{' '}
                    <span className="font-mono bg-gray-100 px-1 py-0.5 rounded">#c8102e</span>
                  </div>
                </div>
              </div>

              <div className="pt-6 border-t border-gray-100 flex gap-4">
                <Button
                  onClick={handleSave}
                  disabled={saving}
                  className="bg-[var(--color-primary)] hover:bg-[#a50e27] text-white flex items-center gap-2"
                >
                  {saving ? <Loader2 size={16} className="animate-spin" /> : <Save size={16} />}
                  Lưu cấu hình
                </Button>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

import React from 'react'
import { Button } from '@/components/ui/button'
import { ArrowLeft } from 'lucide-react'
import {
  SCHEDULE_SIDEBAR,
  ROOMS_SIDEBAR,
  MEETINGS_SIDEBAR,
  LIBRARY_SIDEBAR,
  ADMIN_SIDEBAR,
} from '../../constants/navigation'

const SIDEBAR_MAPS = {
  schedule: SCHEDULE_SIDEBAR,
  rooms: ROOMS_SIDEBAR,
  manage_meetings: MEETINGS_SIDEBAR,
  library: LIBRARY_SIDEBAR,
  admin: ADMIN_SIDEBAR,
}

function SidebarItem({ item, index, activeSidebar, setActiveSidebar, isSidebarCollapsed }) {
  const isActive = activeSidebar === index
  return (
    <button
      onClick={() => setActiveSidebar(index)}
      className={`flex items-center gap-3 px-4 py-3.5 text-sm font-medium text-left border-b border-gray-100 transition-all ${
        isSidebarCollapsed ? 'justify-center' : ''
      }`}
      style={
        isActive
          ? {
              background: 'var(--color-primary, #c8102e)',
              color: '#ffffff',
            }
          : {}
      }
      onMouseEnter={(e) => {
        if (!isActive) {
          e.currentTarget.style.background =
            'color-mix(in srgb, var(--color-primary, #c8102e) 8%, transparent)'
          e.currentTarget.style.color = 'var(--color-primary, #c8102e)'
        }
      }}
      onMouseLeave={(e) => {
        if (!isActive) {
          e.currentTarget.style.background = ''
          e.currentTarget.style.color = ''
        }
      }}
      title={isSidebarCollapsed ? item.label : undefined}
    >
      <item.icon size={20} className="shrink-0" />
      {!isSidebarCollapsed && <span>{item.label}</span>}
    </button>
  )
}

export function AppSidebar({ activeNav, activeSidebar, setActiveSidebar, isSidebarCollapsed }) {
  const items = SIDEBAR_MAPS[activeNav]
  if (!items) return null

  return (
    <aside
      className={`${isSidebarCollapsed ? 'w-16' : 'w-56'} bg-white border-r border-gray-200 flex flex-col shrink-0 shadow-sm z-10 transition-all duration-300 overflow-hidden`}
    >
      {items.map((item, i) => (
        <SidebarItem
          key={item.label}
          item={item}
          index={i}
          activeSidebar={activeSidebar}
          setActiveSidebar={setActiveSidebar}
          isSidebarCollapsed={isSidebarCollapsed}
        />
      ))}

      {/* Back to main system */}
      <div
        className={`mt-auto p-4 border-t border-gray-100 ${isSidebarCollapsed ? 'flex justify-center px-2' : ''}`}
      >
        <Button
          variant="outline"
          className={`w-full text-gray-600 text-sm ${isSidebarCollapsed ? 'justify-center px-2' : 'justify-start'}`}
          style={{
            '--hover-color': 'var(--color-primary, #c8102e)',
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.color = 'var(--color-primary, #c8102e)'
            e.currentTarget.style.background =
              'color-mix(in srgb, var(--color-primary, #c8102e) 6%, transparent)'
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.color = ''
            e.currentTarget.style.background = ''
          }}
          onClick={() => (window.location.href = '/')}
          title={isSidebarCollapsed ? 'Về hệ thống chính' : undefined}
        >
          <ArrowLeft className={isSidebarCollapsed ? 'size-5' : 'mr-2 size-4'} />
          {!isSidebarCollapsed && 'Về hệ thống chính'}
        </Button>
      </div>
    </aside>
  )
}

import React from 'react'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Bell } from 'lucide-react'

export function NotificationsPopover({ notifCount, notifications, markAllRead, markRead }) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button className="p-2 hover:bg-[#a50e27] rounded-full relative transition outline-none">
          <Bell size={17} />
          {notifCount > 0 && (
            <span className="absolute -top-1.5 -right-1.5 min-w-[18px] h-[18px] flex items-center justify-center bg-red-500 text-white text-[10px] font-bold rounded-full border border-white px-1 shadow-sm">
              {notifCount > 99 ? '99+' : notifCount}
