        {/* Divider */}
        <div className="h-px bg-gray-100 mx-6 mt-4" />

        {/* Theme Options */}
        <div className="p-6 bg-white">
          <div className="grid grid-cols-3 gap-3">
            {THEMES.map((theme) => {
              const isActive = selected === theme.id
              return (
                <button
                  key={theme.id}
