                  className={`
                    relative flex flex-col items-center gap-2.5 p-3 rounded-xl border-2 transition-all duration-200
                    ${isActive ? 'border-current shadow-md scale-[1.02]' : 'border-gray-200 hover:border-gray-300 hover:shadow-sm'}
