import { useState, useEffect, useCallback } from 'react'
import { conclusionApi } from '../api/conclusionApi'
import { meetingApi } from '../../meetings/api/meetingApi'

export function useConclusions() {
  const [data, setData] = useState([])
  const [total, setTotal] = useState(0)
  const [meetings, setMeetings] = useState([])
  const [loading, setLoading] = useState(true)
  const [page, setPage] = useState(1)
  const [search, setSearch] = useState('')
  const pageSize = 10

  const fetchData = useCallback(async (currentPage = 1, currentSearch = '') => {
    setLoading(true)
    try {
      const json = await conclusionApi.getAll(currentPage, pageSize, currentSearch)
      const d = Array.isArray(json) ? json : json.data
      if (d && d.items) {
        setData(d.items)
        setTotal(d.total || 0)
      } else if (Array.isArray(d)) {
        setData(d)
        setTotal(d.length)
      }
    } catch {
      setData([])
    } finally {
      setLoading(false)
    }
  }, [])

  const fetchMeetings = useCallback(async () => {
    try {
      const json = await meetingApi.getAll()
      const d = Array.isArray(json) ? json : json.data || []
      setMeetings(d)
    } catch {
      setMeetings([])
    }
  }, [])

  useEffect(() => {
    fetchData(1, '')
    fetchMeetings()
  }, [])

  const createConclusion = useCallback(
    async (body) => {
      const json = await conclusionApi.create(body)
      await fetchData(1, search)
      return json
    },
    [fetchData, search]
  )

  const updateConclusion = useCallback(
    async (id, body) => {
      const json = await conclusionApi.update(id, body)
      await fetchData(page, search)
      return json
    },
    [fetchData, page, search]
  )

  const deleteConclusion = useCallback(
    async (id) => {
      await conclusionApi.delete(id)
      await fetchData(page, search)
    },
    [fetchData, page, search]
  )

  return {
    data,
    total,
    meetings,
    loading,
    page,
    search,
    pageSize,
    setPage,
    setSearch,
    fetchData,
    createConclusion,
    updateConclusion,
    deleteConclusion,
  }
}

import React, { useState } from 'react'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'
import { Checkbox } from '@/components/ui/checkbox'
import {
  Settings2,
  Download,
  Trash2,
  Share2,
  Star,
  FileText,
  File,
  FileSpreadsheet,
  FileImage,
} from 'lucide-react'
import { DocumentUploadModal } from './DocumentUploadModal'
import { documentApi } from '../api/documentApi'

const DEFAULT_COLUMNS = [
  { id: 'name', label: 'Tên tài liệu / Trích yếu', defaultVisible: true },
  { id: 'file', label: 'File tài liệu', defaultVisible: true },
  { id: 'documentType', label: 'Loại tài liệu', defaultVisible: true },
  { id: 'issuingAuthority', label: 'Cơ quan ban hành', defaultVisible: true },
  { id: 'createdAt', label: 'Ngày tạo', defaultVisible: true },
]

const getFileIcon = (ext) => {
  if (!ext) return <File className="w-5 h-5 text-gray-400" />
  switch (ext.toLowerCase()) {
    case '.pdf':
      return <FileText className="w-5 h-5 text-red-500" />
    case '.doc':
    case '.docx':
      return <FileText className="w-5 h-5 text-blue-500" />
    case '.xls':
    case '.xlsx':
      return <FileSpreadsheet className="w-5 h-5 text-green-500" />
    case '.ppt':
    case '.pptx':
      return <FileImage className="w-5 h-5 text-orange-500" />
    default:
      return <File className="w-5 h-5 text-gray-400" />
  }
}

export function DocumentTable({ documents, loading, type, onRefresh }) {
  const [columns, setColumns] = useState(DEFAULT_COLUMNS)
  const [isUploadOpen, setIsUploadOpen] = useState(false)

  const toggleColumn = (id) => {
    setColumns((cols) =>
      cols.map((c) => (c.id === id ? { ...c, defaultVisible: !c.defaultVisible } : c))
    )
  }

  const visibleColumns = columns.filter((c) => c.defaultVisible)

  const handleDelete = async (id) => {
    if (!confirm('Bạn có chắc chắn muốn xóa tài liệu này?')) return
    try {
      await documentApi.deleteDocument(id)
      onRefresh()
    } catch (e) {
      console.error(e)
    }
  }

  const handleToggleImportant = async (doc) => {
    try {
      if (doc.isImportant) {
        await documentApi.unmarkImportant(doc.id)
      } else {
        await documentApi.markImportant(doc.id)
      }
      onRefresh()
    } catch (e) {
      console.error(e)
    }
  }

  if (loading) {
    return <div className="p-8 text-center text-gray-500">Đang tải dữ liệu...</div>
  }

  return (
    <div className="flex flex-col h-full space-y-4">
      {/* Toolbar */}
      <div className="flex justify-between items-center">
        <div className="flex gap-2">
          {(type === 'CaNhan' || type === 'DungChung') && (
            <Button
              onClick={() => setIsUploadOpen(true)}
              className="bg-[var(--color-primary)] hover:bg-red-700 text-white"
            >
              Tải lên tài liệu
            </Button>
          )}
        </div>

        <div className="flex items-center gap-2">
          <Popover>
            <PopoverTrigger asChild>
              <Button variant="outline" size="sm" className="text-gray-600">
                <Settings2 className="w-4 h-4 mr-2" />
                Cấu hình hiển thị
              </Button>
            </PopoverTrigger>
            <PopoverContent className="w-56 p-3">
              <div className="space-y-3">
                <h4 className="font-medium text-sm text-gray-800">Chọn cột hiển thị</h4>
                <div className="space-y-2">
                  {columns.map((col) => (
                    <div key={col.id} className="flex items-center space-x-2">
                      <Checkbox
                        id={`col-${col.id}`}
                        checked={col.defaultVisible}
                        onCheckedChange={() => toggleColumn(col.id)}
                      />
                      <label
                        htmlFor={`col-${col.id}`}
                        className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
                      >
                        {col.label}
                      </label>
                    </div>
                  ))}
                </div>
              </div>
            </PopoverContent>
          </Popover>
        </div>
      </div>

      {/* Table */}
      <div className="border rounded-md bg-white overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              {visibleColumns.map((col) => (
                <TableHead key={col.id} className="font-semibold text-gray-700">
                  {col.label}
                </TableHead>
              ))}
              <TableHead className="w-[120px] text-right">Thao tác</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {documents.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={visibleColumns.length + 1}
                  className="h-32 text-center text-gray-500"
                >
                  Không có tài liệu nào
                </TableCell>
              </TableRow>
            ) : (
              documents.map((doc) => (
                <TableRow key={doc.id}>
                  {visibleColumns.map((col) => {
                    switch (col.id) {
                      case 'name':
                        return (
                          <TableCell key={col.id} className="font-medium text-gray-800">
                            {doc.name}
                          </TableCell>
                        )
                      case 'file':
                        return (
                          <TableCell key={col.id}>
                            <div className="flex items-center gap-2">
                              {getFileIcon(doc.fileType)}
                              <span className="text-sm text-gray-500 uppercase">
                                {doc.fileType?.replace('.', '')}
                              </span>
                            </div>
                          </TableCell>
                        )
                      case 'documentType':
                        return <TableCell key={col.id}>{doc.documentType}</TableCell>
                      case 'issuingAuthority':
                        return <TableCell key={col.id}>{doc.issuingAuthority}</TableCell>
                      case 'createdAt':
                        return (
                          <TableCell key={col.id}>
                            {new Date(doc.createdAt).toLocaleDateString('vi-VN')}
                          </TableCell>
                        )
                      default:
                        return <TableCell key={col.id} />
                    }
                  })}
                  <TableCell className="text-right">
                    <div className="flex items-center justify-end gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        title={doc.isImportant ? 'Bỏ đánh dấu quan trọng' : 'Đánh dấu quan trọng'}
                        onClick={() => handleToggleImportant(doc)}
                      >
                        <Star
                          className={`w-4 h-4 ${doc.isImportant ? 'fill-yellow-400 text-yellow-400' : 'text-gray-400'}`}
                        />
                      </Button>
                      <Button variant="ghost" size="icon" title="Tải xuống" asChild>
                        <a href={doc.filePath} download>
                          <Download className="w-4 h-4 text-blue-600" />
                        </a>
                      </Button>
                      {(type === 'CaNhan' || type === 'DungChung') && (
                        <Button
                          variant="ghost"
                          size="icon"
                          title="Xóa"
                          onClick={() => handleDelete(doc.id)}
                        >
                          <Trash2 className="w-4 h-4 text-red-500" />
                        </Button>
                      )}
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <DocumentUploadModal
        isOpen={isUploadOpen}
        onClose={() => setIsUploadOpen(false)}
        onSuccess={onRefresh}
        type={type}
      />
    </div>
  )
}

import React, { useState, useRef } from 'react'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { UploadCloud, X, Loader2 } from 'lucide-react'
import { documentApi } from '../api/documentApi'

export function DocumentUploadModal({ isOpen, onClose, onSuccess, type, folderId = null }) {
  const [file, setFile] = useState(null)
  const [name, setName] = useState('')
  const [documentType, setDocumentType] = useState('')
  const [issuingAuthority, setIssuingAuthority] = useState('')
  const [isUploading, setIsUploading] = useState(false)
  const fileInputRef = useRef(null)

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files[0]) {
      const selectedFile = e.target.files[0]
      const ext = selectedFile.name.substring(selectedFile.name.lastIndexOf('.')).toLowerCase()
      const allowedExts = ['.doc', '.docx', '.xls', '.xlsx', '.ppt', '.pptx', '.pdf']

      if (!allowedExts.includes(ext)) {
        alert('Định dạng file không hỗ trợ. (Chỉ cho phép: doc, docx, xls, xlsx, ppt, pptx, pdf)')
        e.target.value = null
        return
      }

      setFile(selectedFile)
      if (!name) {
        setName(selectedFile.name)
      }
    }
  }

  const handleUpload = async () => {
    if (!file) {
      alert('Vui lòng chọn file')
      return
    }

    try {
      setIsUploading(true)
      const formData = new FormData()
      formData.append('file', file)
      formData.append('name', name)
      formData.append('documentType', documentType)
      formData.append('issuingAuthority', issuingAuthority)
      formData.append('type', type)
      if (folderId) {
        formData.append('folderId', folderId)
      }

      const res = await documentApi.uploadDocument(formData)
      if (res.success) {
        onSuccess()
        handleClose()
      } else {
        alert(res.message || 'Lỗi khi tải lên')
      }
    } catch (e) {
      console.error(e)
      alert('Có lỗi xảy ra')
    } finally {
      setIsUploading(false)
    }
  }

  const handleClose = () => {
    setFile(null)
    setName('')
    setDocumentType('')
    setIssuingAuthority('')
    if (fileInputRef.current) fileInputRef.current.value = null
    onClose()
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && handleClose()}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Tải lên tài liệu</DialogTitle>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">Tên tài liệu / Trích yếu</label>
            <Input
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Nhập tên hoặc để trống sẽ lấy theo tên file"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">Loại tài liệu (Số ký hiệu)</label>
            <Input
              value={documentType}
              onChange={(e) => setDocumentType(e.target.value)}
              placeholder="VD: 123/QĐ-UBND"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">Cơ quan ban hành</label>
            <Input
              value={issuingAuthority}
              onChange={(e) => setIssuingAuthority(e.target.value)}
              placeholder="Nhập cơ quan ban hành"
            />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-gray-700">File đính kèm</label>
            {!file ? (
              <div
                className="border-2 border-dashed border-gray-200 rounded-lg p-6 flex flex-col items-center justify-center cursor-pointer hover:bg-gray-50 transition-colors"
                onClick={() => fileInputRef.current?.click()}
              >
                <UploadCloud className="w-8 h-8 text-gray-400 mb-2" />
                <p className="text-sm text-gray-600">Click để chọn file</p>
                <p className="text-xs text-gray-400 mt-1">
                  Hỗ trợ .doc, .docx, .xls, .xlsx, .ppt, .pptx, .pdf
                </p>
                <input
                  type="file"
                  ref={fileInputRef}
                  className="hidden"
                  accept=".doc,.docx,.xls,.xlsx,.ppt,.pptx,.pdf"
                  onChange={handleFileChange}
                />
              </div>
            ) : (
              <div className="flex items-center justify-between p-3 border border-gray-200 rounded-lg bg-gray-50 gap-2">
                <div className="flex items-center space-x-3 overflow-hidden min-w-0 flex-1">
                  <div className="p-2 bg-white rounded shadow-sm shrink-0">
                    <UploadCloud className="w-4 h-4 text-gray-500" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium text-gray-700 truncate" title={file.name}>
                      {file.name}
                    </p>
                    <p className="text-xs text-gray-500">
                      {(file.size / 1024 / 1024).toFixed(2)} MB
                    </p>
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => setFile(null)}
                  className="shrink-0"
                >
                  <X className="w-4 h-4 text-gray-500" />
                </Button>
              </div>
            )}
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose} disabled={isUploading}>
            Hủy
          </Button>
          <Button
            onClick={handleUpload}
            disabled={isUploading || !file}
            className="bg-[var(--color-primary)] hover:bg-red-700 text-white"
          >
            {isUploading && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
            Tải lên
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

