            </Button>
            <Button
              className="bg-[var(--color-primary)] hover:bg-[#a50e27] text-white"
              onClick={handleAddFolder}
            >
              Lưu
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Dialog>
  )
}

import { useState, useEffect, useRef } from 'react'

export function useMeetingCreate({ onSaved }) {
  const [step, setStep] = useState(1)
  const [loading, setLoading] = useState(false)
  const [rooms, setRooms] = useState([])
  const [proceedings, setProceedings] = useState([])
  const [users, setUsers] = useState([])
  const [departments, setDepartments] = useState([])
  const [formData, setFormData] = useState({
    title: '',
    proceedingId: '',
    singleContent: false,
    startTime: '',
    endTime: '',
    roomId: '',
    meetingType: '',
    onlineMeetingUrl: '',
    location: '',
  })
  const [selectedUsers, setSelectedUsers] = useState([])
  const [programFiles, setProgramFiles] = useState([])
  const [invitationFiles, setInvitationFiles] = useState([])
  const [participantTab, setParticipantTab] = useState('NhomThanhVien')
  const [groupType, setGroupType] = useState('')
  const [participantSearch, setParticipantSearch] = useState('')
  const [presidingUsers, setPresidingUsers] = useState([])
  const [contentTabs, setContentTabs] = useState([
    { id: 1, title: 'Nội dung 1' },
    { id: 2, title: 'Nội dung 2' },
    { id: 3, title: 'Nội dung 3' },
    { id: 4, title: 'Nội dung 4' },
  ])
  const [activeContentTab, setActiveContentTab] = useState(4)
  const programInputRef = useRef(null)
  const invitationInputRef = useRef(null)

  useEffect(() => {
    fetch('/api/phonghopkhonggiayto/rooms')
      .then((r) => r.json())
      .then((json) => setRooms(Array.isArray(json) ? json : json.data || []))
      .catch(() => {})

    fetch('/api/phonghopkhonggiayto/proceedings')
      .then((r) => r.json())
      .then((json) => setProceedings(Array.isArray(json) ? json : json.data || []))
      .catch(() => {})

    fetch('/api/users')
      .then((r) => r.json())
      .then((json) => setUsers(Array.isArray(json) ? json : json.data || []))
      .catch(() => {})

    fetch('/api/users/departments')
      .then((r) => r.json())
      .then((json) => setDepartments(Array.isArray(json) ? json : json.data || []))
      .catch(() => {})
  }, [])

  const usersInSelectedDept = groupType
    ? users.filter((u) => u.departmentId === Number(groupType))
    : users

  const handleFileChange = (e, setFiles) => {
    if (e.target.files) setFiles((prev) => [...prev, ...Array.from(e.target.files)])
  }
  const removeFile = (idx, setFiles) => setFiles((prev) => prev.filter((_, i) => i !== idx))

  const handleSubmit = async () => {
    if (!formData.title || !formData.startTime || !formData.endTime) {
      alert('Vui lòng nhập đầy đủ tên phiên họp và thời gian')
      return
    }
    setLoading(true)
    const requestJson = {
      title: formData.title,
      startTime: formData.startTime,
      endTime: formData.endTime,
      roomId: formData.roomId ? parseInt(formData.roomId) : null,
      location: formData.location,
      proceedingId: formData.proceedingId ? parseInt(formData.proceedingId) : null,
      meetingType: formData.meetingType,
      onlineMeetingUrl: formData.onlineMeetingUrl,
      participantUserIds: selectedUsers,
    }
    const fd = new FormData()
    fd.append('requestJson', JSON.stringify(requestJson))
    programFiles.forEach((f) => fd.append('programFiles', f))
    invitationFiles.forEach((f) => fd.append('invitationFiles', f))
    try {
      const res = await fetch('/api/phonghopkhonggiayto/meetings', { method: 'POST', body: fd })
      const json = await res.json()
      if (res.ok && !json.error) onSaved()
      else alert(json.message || json.error || 'Có lỗi xảy ra')
    } catch {
      alert('Lỗi kết nối máy chủ')
    } finally {
      setLoading(false)
    }
  }

  return {
    step,
    setStep,
    loading,
    rooms,
    proceedings,
    users,
    departments,
    usersInSelectedDept,
    formData,
    setFormData,
    selectedUsers,
    setSelectedUsers,
    programFiles,
    setProgramFiles,
    invitationFiles,
    setInvitationFiles,
    participantTab,
    setParticipantTab,
    groupType,
    setGroupType,
    participantSearch,
    setParticipantSearch,
    presidingUsers,
    setPresidingUsers,
    contentTabs,
    setContentTabs,
    activeContentTab,
    setActiveContentTab,
    programInputRef,
    invitationInputRef,
    handleFileChange,
    removeFile,
    handleSubmit,
  }
}

import { useState, useEffect, useCallback } from 'react'
import { meetingApi } from '../api/meetingApi'
import { ROLES } from '../../../constants/roles'
import { ATTENDANCE_STATUS } from '../../../constants/meeting'

function getRole() {
  try {
    const token = localStorage.getItem('auth_token')
    if (token) {
      const payload = JSON.parse(window.atob(token.split('.')[1]))
      return (
        payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
        payload.role ||
        payload.Role
      )
    }
    return null
  } catch {
    return null
  }
}

export function useMeetingList() {
  const role = getRole()
  const isAdmin = role === ROLES.ADMIN || role === ROLES.LANH_DAO

  const [meetings, setMeetings] = useState([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState('invited')

  const fetchMeetings = useCallback(
    (tab = activeTab) => {
      setLoading(true)
      const url =
        isAdmin && tab === 'all'
          ? '/api/phonghopkhonggiayto/meetings/schedule'
          : '/api/phonghopkhonggiayto/meetings/my-meetings'

      fetch(url)
        .then((r) => r.json())
        .then((json) => {
          const data = Array.isArray(json) ? json : json.data || []
          setMeetings(
            data.map((m) => ({
              ...m,
              attendanceStatus: m.participants?.[0]?.attendanceStatus ?? ATTENDANCE_STATUS.PENDING,
            }))
          )
        })
        .catch(() => {})
        .finally(() => setLoading(false))
    },
    [isAdmin, activeTab]
  )

  const deleteMeeting = useCallback(
    async (id) => {
      try {
        const res = await fetch(`/api/phonghopkhonggiayto/meetings/${id}`, { method: 'DELETE' })
        const json = await res.json()
        if (json.success) {
          fetchMeetings(activeTab)
        } else {
          alert('Có lỗi xảy ra: ' + (json.message || 'Không thể xóa phiên họp.'))
        }
      } catch {
        alert('Lỗi kết nối máy chủ.')
      }
    },
    [activeTab, fetchMeetings]
  )

  const confirmAttendance = useCallback(
    async (meetingId, status) => {
      try {
        const json = await meetingApi.updateAttendance(meetingId, status)
        if (json.success) {
          fetchMeetings(activeTab)
        } else {
          alert('Có lỗi xảy ra: ' + (json.message || 'Không thể xác nhận tham gia.'))
        }
      } catch {
        alert('Lỗi kết nối máy chủ.')
      }
    },
    [activeTab, fetchMeetings]
  )

  useEffect(() => {
    fetchMeetings(activeTab)
    const handler = () => fetchMeetings(activeTab)
    document.addEventListener('realtime:meeting_updated', handler)
    return () => document.removeEventListener('realtime:meeting_updated', handler)
  }, [activeTab])

  return {
    meetings,
    loading,
    activeTab,
    setActiveTab,
    isAdmin,
    fetchMeetings,
    deleteMeeting,
    confirmAttendance,
  }
}

import { useState, useEffect, useCallback } from 'react'
import { meetingApi } from '../api/meetingApi'
import { ROLES } from '../../../../constants/roles'

const getRole = () => {
  try {
    const token = localStorage.getItem('auth_token')
    if (token) {
      const payload = JSON.parse(window.atob(token.split('.')[1]))
      return (
        payload['http://schemas.microsoft.com/ws/2008/06/identity/claims/role'] ||
        payload.role ||
        payload.Role
      )
    }
    return null
  } catch {
    return null
  }
}

export function useMeetings(initialTab = 'invited') {
  const [meetings, setMeetings] = useState([])
  const [loading, setLoading] = useState(true)
  const [activeTab, setActiveTab] = useState(initialTab)
  const role = getRole()
  const isAdmin = role === ROLES.ADMIN || role === ROLES.LANH_DAO

  const fetchMeetings = useCallback(
    async (tab = activeTab) => {
      setLoading(true)
      try {
        const isAllTab = isAdmin && tab === 'all'
        const json = isAllTab ? await meetingApi.getAll() : await meetingApi.getMyMeetings()
        const data = Array.isArray(json) ? json : json.data || []
        setMeetings(
          data.map((m) => ({
            ...m,
            attendanceStatus: m.participants?.[0]?.attendanceStatus ?? 'Chưa xác nhận',
          }))
        )
      } catch {
        setMeetings([])
      } finally {
        setLoading(false)
      }
    },
    [activeTab, isAdmin]
  )

  useEffect(() => {
    fetchMeetings(activeTab)
    const handler = () => fetchMeetings(activeTab)
    document.addEventListener('realtime:meeting_updated', handler)
    return () => document.removeEventListener('realtime:meeting_updated', handler)
  }, [activeTab])

  const deleteMeeting = useCallback(async (id) => {
    try {
      await meetingApi.delete(id)
      setMeetings((prev) => prev.filter((m) => m.id !== id))
      return true
    } catch {
      alert('Lỗi kết nối máy chủ.')
      return false
    }
  }, [])

  return { meetings, loading, activeTab, setActiveTab, isAdmin, fetchMeetings, deleteMeeting }
}

