                          <button
                            onClick={(e) => {
                              e.stopPropagation()
                              setSendConfirmId(q.id)
                            }}
                            className="text-xs text-blue-600 hover:text-blue-800 border border-blue-200 hover:bg-blue-50 px-2 py-1 rounded-md flex items-center gap-1 transition"
